design.compositionCss:
/* Silver Screen: original quiet cinema composition with pale-blue frame rules. */
.shell{display:grid;grid-template-columns:212px minmax(0,1fr)}
.sidebar{display:flex;flex-direction:column;position:sticky;top:0;height:100dvh;gap:18px;padding:28px 16px;border:0;border-right:1px solid var(--weekly-soft);overflow-y:auto}
.brand{margin:0 0 16px}
.brand strong{font-family:var(--body);font-size:14px;font-weight:600;line-height:1.4}
.brand small{font-size:10px}
.sidebar nav{display:grid;grid-template-columns:minmax(0,1fr);gap:5px}
.nav-item{display:flex;align-items:center;gap:12px;min-height:45px;padding:11px 12px;border:0;border-radius:8px;font-family:var(--body);font-size:12px;line-height:1.4}
.nav-item span{font-family:var(--body);font-size:10px;min-width:20px;letter-spacing:.03em}
.sidebar-foot{display:grid;gap:8px;margin-top:auto;padding-top:20px;border:0}
.sidebar-foot .quiet{min-width:0;text-align:left;border-radius:8px}
main{max-width:1560px;margin:auto;padding:0 36px 80px}
.topbar{min-height:120px;padding:28px 0;margin-bottom:26px;border:0}
.topbar h1{font-family:var(--body);font-weight:600;font-size:clamp(28px,3vw,39px);line-height:1.25;letter-spacing:-.04em}
.eyebrow,.topbar .eyebrow,.panel .eyebrow{color:var(--weekly-mark)}
.primary,.quiet{border-radius:8px;min-height:44px}
.primary{background:var(--acid);color:var(--stage);border-color:var(--acid)}
.quiet{background:var(--panel);color:var(--ink);border-color:var(--weekly-soft)}
.panel,.module,.phase,.resource,.evidence-card,.production,.daily-review,.stat-card:nth-child(n),.cinema-film{padding:24px;border:1px solid var(--weekly-soft);border-radius:12px;box-shadow:none}
.panel h2,.intro-panel h2{font-family:var(--body);font-size:24px;font-weight:600;line-height:1.35;letter-spacing:-.03em;border:0;padding-bottom:0}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.poster-focus{grid-column:1/-1;grid-row:auto;min-height:490px;padding:38px;border:1px solid var(--weekly-soft);border-left:5px solid var(--weekly-mark);border-radius:18px}
.poster-focus h2{font-family:var(--display);font-size:clamp(58px,6.8vw,92px);font-weight:400;line-height:1.1;letter-spacing:-.06em;max-width:840px;margin-bottom:26px}
.poster-focus h2 span{font-family:var(--script);font-size:1.08em;font-weight:600;font-style:italic;line-height:1.05;letter-spacing:-.05em;margin-top:6px}
.poster-focus .hero-script{font-family:var(--body);font-size:16px!important;line-height:1.6;letter-spacing:.04em;margin:0 0 24px}
.poster-focus .cinema-scene{width:47%;right:0;top:0;opacity:.5;transform:none}
.poster-focus .hero-star{width:50px;height:50px;top:26px;right:26px;border:1px solid var(--weekly-mark);border-radius:50%;background:var(--stage)}
.poster-focus .progress-wrap{max-width:370px;margin-top:28px}
.hero-grid .stat-card{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-column:auto;grid-row:auto;gap:7px 14px;align-items:center;min-height:116px;padding:22px;background:var(--panel);border:1px solid var(--weekly-soft)}
.hero-grid .stat-card strong{grid-column:2;grid-row:1/3;font-family:var(--script);font-weight:600;font-size:44px;line-height:1;margin:0;letter-spacing:-.04em}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:10px;line-height:1.6}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px;margin:26px 0 32px;border:0}
.studio-programme button{min-height:112px;padding:22px!important;border:1px solid var(--weekly-soft)!important;border-top:3px solid var(--weekly-mark)!important;border-radius:12px;background:var(--panel);box-shadow:none}
.studio-programme span{font-family:var(--body);font-size:17px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.module h3{font-family:var(--script);font-size:34px;font-weight:600;line-height:1.15;letter-spacing:-.03em}
.module-head small{font-family:var(--body);font-size:11px;font-style:normal;line-height:1.6}
.topic{font-size:13px;line-height:1.6}
.roadmap{display:grid;columns:auto;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.phase:nth-child(n){display:block;margin:0!important;padding:26px;min-height:245px;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark);border-radius:12px}
.phase h3{font-family:var(--script);font-size:34px;font-weight:600;line-height:1.15;letter-spacing:-.03em}
.phase small{font-family:var(--body);font-size:10px;letter-spacing:.1em}
.resource-list{grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}
.resource{display:block;padding:26px;border:1px solid var(--weekly-soft);border-bottom:3px solid var(--weekly-mark)}
.resource h3{font-family:var(--body);font-size:17px;font-weight:600;line-height:1.4;letter-spacing:-.02em}
.resource div{margin-bottom:16px}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
.evidence-card label{font-family:var(--body);font-size:15px;line-height:1.5}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.cinema-film{padding:24px}
.film-cover{min-height:320px;border:0;border-radius:10px;box-shadow:none;background:var(--weekly-soft)}
.cinema-film .film-cover h3{font-family:var(--script);font-size:52px;font-weight:600;line-height:1.05;letter-spacing:-.035em}
.film-cover h3 small,.cover-caption{color:var(--ink)}
.cinema-intro{padding:32px;border:1px solid var(--weekly-soft);border-radius:18px}
.cinema-intro h2{font-family:var(--script);font-size:clamp(40px,4.5vw,64px);font-weight:600;line-height:1.15;letter-spacing:-.035em}
.cinema-source-note,.cinema-credits,.meta,.studio-footer{color:var(--ink)}
.journal-masthead{padding:30px 0;border-bottom:1px solid var(--weekly-soft)}
.journal-masthead h2{font-family:var(--script);font-size:clamp(76px,8vw,112px);font-weight:600;line-height:1.1;letter-spacing:-.05em}
.journal-masthead h2 em{font-family:var(--display);font-size:.62em;font-style:normal;line-height:1.2;letter-spacing:-.05em}
.journal-seal{border:1px solid var(--weekly-mark);border-radius:50%;background:var(--panel);transform:rotate(-6deg)}
.journal-workbench{grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:24px}
.journal-bridge{transform:none}
.journal-section-title{border-top:1px solid var(--weekly-soft)}
.journal-section-title h2{font-family:var(--body);font-size:25px;font-weight:600;line-height:1.3;letter-spacing:-.03em}
#view-journal .journal-deck{gap:22px;border:0}
.diary-card:not(.poster-card){transform:none;margin:0;padding:24px;border:1px solid var(--weekly-soft);border-radius:12px;box-shadow:none}
#view-journal .diary-card.poster-card{border-radius:10px}
.journal-empty{border-color:var(--weekly-soft);border-radius:12px}
.journal-empty h3{font-size:44px;line-height:1.2}
.form-panel input,.form-panel select,.form-panel textarea,.filter-row input,.filter-row select{border:1px solid var(--weekly-soft);border-radius:8px;background:var(--stage);color:var(--ink)}
.filter-row{border:1px solid var(--weekly-soft);border-radius:12px;background:var(--panel)}
.tag{border-radius:5px}
@media(max-width:1100px) and (min-width:761px){
.shell{grid-template-columns:188px minmax(0,1fr)}
.sidebar nav{grid-template-columns:minmax(0,1fr)}
main{padding:0 24px 64px}
.journal-workbench{grid-template-columns:minmax(0,1fr)}
.evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:760px){
.shell{display:block}
.sidebar{display:block;position:relative;height:auto;padding:20px;border:0;border-bottom:1px solid var(--weekly-soft)}
.brand{margin:0}
.sidebar-foot{display:flex;flex-wrap:wrap;margin-top:14px;padding:0}
.sidebar-foot .quiet{font-size:10px;padding:10px}
main{padding:0 20px 64px}
.topbar{min-height:0;padding:24px 0;margin-bottom:20px}
.topbar h1{font-size:28px;line-height:1.3}
.top-actions{margin-top:14px}
.poster-focus{min-height:480px;padding:28px 22px;border:1px solid var(--weekly-soft);border-left:4px solid var(--weekly-mark);border-radius:16px}
.poster-focus h2{font-size:clamp(44px,12.3vw,66px);line-height:1.15}
.poster-focus .hero-script{font-size:14px!important}
.poster-focus .cinema-scene{width:78%;right:-18%;opacity:.3}
.poster-focus .hero-star{width:30px;height:30px}
.hero-grid .stat-card{display:flex;flex-direction:column;align-items:start;gap:6px;min-height:124px;padding:16px 10px}
.hero-grid .stat-card strong{font-size:32px;margin:4px 0}
.hero-grid .stat-card span,.hero-grid .stat-card small{font-size:9px;letter-spacing:0}
.studio-programme,.syllabus-grid,.roadmap,.resource-list,.evidence-grid,.cinema-grid{grid-template-columns:minmax(0,1fr);gap:16px}
.studio-programme button{min-height:98px;padding:22px!important}
.panel,.module,.resource,.evidence-card,.production,.daily-review,.cinema-film{padding:22px}
.panel h2,.intro-panel h2{font-size:23px;line-height:1.35}
.phase:nth-child(n){min-height:0;padding:24px}
.module h3,.phase h3{font-size:30px}
.resource h3{font-size:17px}
.film-cover{min-height:280px}
.cinema-film .film-cover h3{font-size:43px;line-height:1.1}
.journal-masthead h2{font-size:clamp(52px,14.5vw,74px);line-height:1.25;overflow-wrap:anywhere}
.journal-masthead h2 em{font-size:.65em}
#view-journal .journal-workbench{grid-template-columns:minmax(0,1fr)}
#view-journal .journal-workbench :is(.form-panel,.journal-bridge){min-width:0;max-width:100%}
#view-journal .journal-workbench :is(form,details,label,small,p,div){min-width:0;max-width:100%;overflow-wrap:anywhere}
#view-journal .form-panel,#view-journal .form-row{grid-template-columns:minmax(0,1fr)}
#view-journal .panel-head{flex-direction:column;align-items:start}
#view-journal .journal-workbench :is(input,select,textarea){min-width:0;max-width:100%;width:100%;box-sizing:border-box}
#view-journal .journal-check input{flex-shrink:0}
#view-journal .journal-workbench :is(button,a){max-width:100%;white-space:normal;overflow-wrap:anywhere}
#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}
#view-journal .diary-card:nth-child(n){transform:none;box-shadow:none}
#view-journal .journal-empty{min-width:0;padding:34px 14px}
#view-journal .journal-empty h3{font-size:38px;overflow-wrap:anywhere}
#view-journal .journal-watch-shelf{min-width:0;overflow-wrap:anywhere}
#view-journal .watch-ticket{flex-wrap:wrap}
}
